BEGIN;
UPDATE rekening SET saldo = saldo - 500
 WHERE id = 1;
UPDATE rekening SET saldo = saldo + 500
 WHERE id = 2;
COMMIT;   -- atau ROLLBACK;

BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT sum(saldo) FROM rekening;
-- transaksi lain commit di sini
SELECT sum(saldo) FROM rekening;
-- hasil sama dengan yang pertama
COMMIT;

BEGIN;
SELECT saldo FROM rekening
 WHERE id = 1 FOR UPDATE;
-- baris terkunci sampai COMMIT
UPDATE rekening SET saldo = saldo - 500
 WHERE id = 1;
COMMIT;

CREATE FUNCTION set_waktu() RETURNS trigger AS $$
BEGIN
  NEW.diperbarui_pada := now();
  RETURN NEW;
END $$ LANGUAGE plpgsql;

CREATE TRIGGER trg_waktu BEFORE UPDATE
  ON produk FOR EACH ROW
  EXECUTE FUNCTION set_waktu();

